# 无向图哈密顿通路存在性(状压DP, n<=20)
dp[mask][v] = False, 初始化 dp[1<<s][s]=True (所有起点)
for mask in 1..full:
    for v in mask 中每个顶点:
        if not dp[mask][v]: continue
        for w in 邻接[v]:
            if w not in mask:
                dp[mask|1<<w][w] = True
存在 dp[full][v]=True 即存在哈密顿通路
(回路: 另需 v 与起点 s 有边)
